import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"问题码","description":"","frontmatter":{},"headers":[],"relativePath":"reference/issues.md","filePath":"reference/issues.md","lastUpdated":1792353976000}`),a={name:`reference/issues.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="问题码" tabindex="-1">问题码 <a class="header-anchor" href="#问题码" aria-label="Permalink to “问题码”">​</a></h1><p><code>readDocument</code> 读入与 <code>validateDocument</code> 校验给出的问题都带问题码、从文档根算起的路径、所在对象与严重程度，不带文案；设计器的问题列表与属性面板按语言包把问题码换成说明。说明里花括号括起的是问题参数。</p><h2 id="校验" tabindex="-1">校验 <a class="header-anchor" href="#校验" aria-label="Permalink to “校验”">​</a></h2><p><code>validateDocument</code> 按节点类型、属性描述与扩展的规则检查流程定义。下表列出内置的问题码、缺省严重程度与中文语言包的说明；严重程度可以经 <code>FlowValidateOptions.severity</code> 按问题码改写，写 <code>off</code> 即不报告。不带点号的问题码（<code>required</code>、<code>invalid-type</code>、<code>out-of-range</code>、<code>not-integer</code>、<code>invalid-option</code>、<code>invalid-color</code>、<code>invalid-value</code>、<code>duplicate-value</code>、<code>unknown-key</code>、<code>unknown-control</code>）来自属性的检查，路径落在那个属性上。</p><table tabindex="0"><thead><tr><th>问题码</th><th>缺省严重程度</th><th>说明</th></tr></thead><tbody><tr><td><code>node.duplicate-id</code></td><td>错误</td><td>节点 id「{id}」重复</td></tr><tr><td><code>node.unknown-type</code></td><td>错误</td><td>节点类型「{type}」没有登记</td></tr><tr><td><code>edge.duplicate-id</code></td><td>错误</td><td>连线 id「{id}」重复</td></tr><tr><td><code>edge.dangling</code></td><td>错误</td><td>连线指向不存在的节点「{node}」</td></tr><tr><td><code>edge.unknown-port</code></td><td>错误</td><td>端口「{port}」不存在</td></tr><tr><td><code>edge.invalid-direction</code></td><td>错误</td><td>端口方向不允许这样连接</td></tr><tr><td><code>edge.self-loop</code></td><td>错误</td><td>节点不能连向自己</td></tr><tr><td><code>edge.target-not-allowed</code></td><td>错误</td><td>「{sourceType}」不能连向「{targetType}」</td></tr><tr><td><code>edge.source-not-allowed</code></td><td>错误</td><td>「{targetType}」不接受来自「{sourceType}」的连线</td></tr><tr><td><code>node.max-incoming</code></td><td>错误</td><td>入线最多 {max} 条，现有 {count} 条</td></tr><tr><td><code>node.max-outgoing</code></td><td>错误</td><td>出线最多 {max} 条，现有 {count} 条</td></tr><tr><td><code>port.max-connections</code></td><td>错误</td><td>端口「{port}」最多连 {max} 条，现有 {count} 条</td></tr><tr><td><code>type.min-count</code></td><td>错误</td><td>至少需要 {min} 个「{type}」，现有 {count} 个</td></tr><tr><td><code>type.max-count</code></td><td>错误</td><td>「{type}」最多 {max} 个，现有 {count} 个</td></tr><tr><td><code>node.isolated</code></td><td>警告</td><td>没有任何连线</td></tr><tr><td><code>node.missing-incoming</code></td><td>警告</td><td>缺少入线</td></tr><tr><td><code>node.missing-outgoing</code></td><td>警告</td><td>缺少出线</td></tr><tr><td><code>node.unreachable</code></td><td>警告</td><td>从开始节点走不到这里</td></tr><tr><td><code>required</code></td><td>错误</td><td>必填</td></tr><tr><td><code>invalid-type</code></td><td>错误</td><td>取值类型不对</td></tr><tr><td><code>out-of-range</code></td><td>错误</td><td>超出允许的范围</td></tr><tr><td><code>not-integer</code></td><td>错误</td><td>必须是整数</td></tr><tr><td><code>invalid-option</code></td><td>错误</td><td>不在可选项里</td></tr><tr><td><code>invalid-color</code></td><td>错误</td><td>不是有效的颜色</td></tr><tr><td><code>invalid-value</code></td><td>错误</td><td>取值不合法</td></tr><tr><td><code>duplicate-value</code></td><td>错误</td><td>选项的值重复</td></tr><tr><td><code>unknown-key</code></td><td>错误</td><td>含有不认识的字段</td></tr><tr><td><code>unknown-control</code></td><td>错误</td><td>没有这种编辑方式</td></tr></tbody></table><p>扩展登记的规则自带问题码（如预设的 <code>xihan-workflow.*</code>），说明由扩展的 <code>issueText</code> 给出。</p><h2 id="读入" tabindex="-1">读入 <a class="header-anchor" href="#读入" aria-label="Permalink to “读入”">​</a></h2><p><code>readDocument</code> 把未知输入读成流程定义：结构问题用 XiHan.UI <code>@xihan-ui/designer-kit</code> 的通用问题码（取值类型不对、缺少必填字段、多出不认识的字段等），见 <a href="https://ui.docs.xihanfun.com/runtime/designer-kit" target="_blank" rel="noreferrer">designer-kit 的问题形状</a>。流程自己的读入问题码只有一个：</p><table tabindex="0"><thead><tr><th>问题码</th><th>说明</th></tr></thead><tbody><tr><td><code>document.unsupported-version</code></td><td><code>version</code> 不是当前支持的版本；参数 <code>version</code> 是读到的版本，<code>supported</code> 是支持的版本</td></tr></tbody></table>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};